require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v2.php';api_v2_require_enabled();api_v2_rate_limit();if($_SERVER['REQUEST_METHOD']!=='POST')api_v2_error('POST required',405);$in=api_input();$login=trim((string)($in['login']??''));$pass=(string)($in['password']??'');$appType=api_v2_app_type($in);if($login===''||$pass==='')api_v2_error('Login and password are required.',422);try{security_assert_login_allowed($login);$q=db()->prepare("SELECT * FROM users WHERE (email=? OR phone=?) AND status='active' LIMIT 1");$q->execute([$login,$login]);$u=$q->fetch();if(!$u||!password_verify($pass,(string)$u['password_hash'])){security_record_login(false,$login,$u?(int)$u['id']:null,'mobile_v2','Invalid credentials');api_v2_error('Invalid credentials.',401);}if(function_exists('user_is_approved')&&!user_is_approved((int)$u['id']))api_v2_error('Account is not approved for access.',403);if($appType==='seller'){if(($u['role']??'')!=='shopkeeper'){try{$s=db()->prepare('SELECT id FROM seller_staff WHERE staff_user_id=? AND status=1 LIMIT 1');$s->execute([(int)$u['id']]);if(!$s->fetchColumn())api_v2_error('This account does not have Seller App access.',403);}catch(Throwable $e){api_v2_error('Seller App access is unavailable.',403);}}}if(security_role_requires_2fa($u)){security_issue_otp($u,'mobile_api_v2');$challenge='ch2_'.bin2hex(random_bytes(24));db()->prepare("INSERT INTO mobile_api_challenges(user_id,challenge_hash,device_name,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL 10 MINUTE))")->execute([(int)$u['id'],hash('sha256',$challenge),substr((string)($in['device_name']??'Mobile App'),0,160)]);api_v2_ok(['two_factor_required'=>true,'challenge'=>$challenge,'app_type'=>$appType]);}$auth=api_v2_issue_session($u,$in);security_record_login(true,$login,(int)$u['id'],'mobile_v2');api_v2_event((int)$u['id'],'auth.login',$in);api_v2_ok(['two_factor_required'=>false,'auth'=>$auth,'user'=>api_v2_user_public($u),'app_type'=>$appType],(int)$u['id']);}catch(Throwable $e){api_v2_error($e->getMessage(),429);}
